INSERT INTO topics (id, subject_id, name, description, difficulty_level)
VALUES ('c21cf039-3759-4b4d-9dce-129db79eff41', (SELECT id FROM subjects WHERE name = 'Ciencias Naturales'), 'Selección natural', 'Tema: Selección natural', 1)
ON CONFLICT (name, subject_id) DO NOTHING;
INSERT INTO questions (
    id, topic_id, subject_id, question_text, question_type,
    difficulty, correct_answer, options, explanation, hint,
    tags, power_stats,
    pregunta_texto, pregunta_imagen,
    opcion_a_texto, opcion_b_texto, opcion_c_texto, opcion_d_texto,
    respuesta_correcta
) VALUES (
    'e0d4d97b-ac2f-4d5b-8f5d-1c5a70cf2b44',
    (SELECT id FROM topics WHERE name = 'Selección natural' AND subject_id = (SELECT id FROM subjects WHERE name = 'Ciencias Naturales') LIMIT 1),
    (SELECT id FROM subjects WHERE name = 'Ciencias Naturales'),
    'De acuerdo con la gráfica de predación del grupo de aves, Los depredadores cazan más fácilmente las de un color que otras. ¿Las de qué color tienen mayor probabilidad de supervivencia?',
    'multiple_choice',
    5,
    'A',
    '{"A": "Las de color naranja y amarillo, ya que la selecci\u00f3n natural act\u00faa para incrementar la frecuencia de las mutaciones ventajosas (Su color diferente al marr\u00f3n), que es como se produce el cambio evolutivo. Esos organismos con mutaciones ventajosas tienen m\u00e1s posibilidades de sobrevivir, reproducirse y transmitir las mutaciones a su descendencia.", "B": "Las de color amarillo porque la depredaci\u00f3n aumenta cuanto mayor es el n\u00famero de las presas y como consecuencia aumentar\u00e1 la poblaci\u00f3n de depredadores.", "C": "Las de color marr\u00f3n y rojo porque cada depredador va desarrollando h\u00e1bitos y t\u00e9cnicas de caza que le hacen m\u00e1s eficaces sus capturas y las presas asimismo para evitarlas, Los depredadores desempe\u00f1aban el papel de agentes de la selecci\u00f3n natural, al eliminar aquellas aves m\u00e1s parecidas a las de su dieta.", "D": "Las de color rojo, porque la selecci\u00f3n natural act\u00faa sobre los genes a trav\u00e9s de los fenotipos: los genes se perpet\u00faan en la medida en que dan lugar a fenotipos que presentan ventajas selectivas sobre otros fenotipos competidores."}',
    'Los colores menos predados tienen ventaja selectiva',
    'Comprende selección natural',
    '["Explicaci\u00f3n de fen\u00f3menos", "Analizar"]',
    '{"discrimination_index": 0.5, "success_rate": 0.6, "estimated_time": 19, "xp_reward": 19, "original_id": "39", "bank_origin": "ICFES_OFICIAL"}',
    'De acuerdo con la gráfica de predación del grupo de aves, Los depredadores cazan más fácilmente las de un color que otras. ¿Las de qué color tienen mayor probabilidad de supervivencia?',
    NULL,
    'Las de color naranja y amarillo, ya que la selección natural actúa para incrementar la frecuencia de las mutaciones ventajosas (Su color diferente al marrón), que es como se produce el cambio evolutivo. Esos organismos con mutaciones ventajosas tienen más posibilidades de sobrevivir, reproducirse y transmitir las mutaciones a su descendencia.',
    'Las de color amarillo porque la depredación aumenta cuanto mayor es el número de las presas y como consecuencia aumentará la población de depredadores.',
    'Las de color marrón y rojo porque cada depredador va desarrollando hábitos y técnicas de caza que le hacen más eficaces sus capturas y las presas asimismo para evitarlas, Los depredadores desempeñaban el papel de agentes de la selección natural, al eliminar aquellas aves más parecidas a las de su dieta.',
    'Las de color rojo, porque la selección natural actúa sobre los genes a través de los fenotipos: los genes se perpetúan en la medida en que dan lugar a fenotipos que presentan ventajas selectivas sobre otros fenotipos competidores.',
    'a'
);

