    '["Indagaci\u00f3n", "Analizar"]',
    '{"discrimination_index": 0.5, "success_rate": 0.6, "estimated_time": 42, "xp_reward": 42, "original_id": "128", "bank_origin": "ICFES_OFICIAL"}',
