VALUES ('8eec6885-b70c-496c-9ec4-3c0017700660', (SELECT id FROM subjects WHERE name = 'Ciencias Naturales'), 'Carga eléctrica y conductividad', 'Tema: Carga eléctrica y conductividad', 1)
