VALUES ('a0cfafa2-8cb7-4345-ad4d-167acff75219', (SELECT id FROM subjects WHERE name = 'Ciencias Naturales'), 'Ciclo del nitrógeno y eutrofización', 'Tema: Ciclo del nitrógeno y eutrofización', 1)
ON CONFLICT (name, subject_id) DO NOTHING;
INSERT INTO questions (
    id, topic_id, subject_id, question_text, question_type,
    difficulty, correct_answer, options, explanation, hint,
    tags, power_stats,
    pregunta_texto, pregunta_imagen,
    opcion_a_texto, opcion_b_texto, opcion_c_texto, opcion_d_texto,
    respuesta_correcta
) VALUES (
    'e30561e9-044c-4cec-8971-f5aa8f8d1745',
    (SELECT id FROM topics WHERE name = 'Ciclo del nitrógeno y eutrofización' AND subject_id = (SELECT id FROM subjects WHERE name = 'Ciencias Naturales') LIMIT 1),
    (SELECT id FROM subjects WHERE name = 'Ciencias Naturales'),
    'Para mantener peces en acuarios se debe tener en cuenta el "síndrome de tanque nuevo" que se produce cuando los peces mueren envenenados por altos niveles de amoniaco (NH₃). El amoniaco se produce por la mineralización de los desechos de los peces, el exceso de comida y la descomposición de tejidos animales y vegetales. Una estrategia para disminuir esta mortalidad es asegurar la circulación de estas sustancias a través del ciclo del nitrógeno. ¿Cuál de las siguientes prácticas permitiría que el ciclo del nitrógeno se dé en el acuario?',
    'multiple_choice',
    5,
    'C',
