VALUES ('8ed30674-3ac6-4a64-a5af-f396153752c1', (SELECT id FROM subjects WHERE name = 'Ciencias Sociales'), 'Conflictos religiosos y multiculturalismo', 'Tema: Conflictos religiosos y multiculturalismo', 1)
