VALUES ('af4e21a9-c690-4aba-b0ae-87238f7c260d', (SELECT id FROM subjects WHERE name = 'Ciencias Sociales'), 'Conflictos laborales y autonomía profesional', 'Tema: Conflictos laborales y autonomía profesional', 1)
