INSERT INTO questions (
    id, topic_id, subject_id, question_text, question_type,
    difficulty, correct_answer, options, explanation, hint,
    tags, power_stats,
    pregunta_texto, pregunta_imagen,
    opcion_a_texto, opcion_b_texto, opcion_c_texto, opcion_d_texto,
    respuesta_correcta
) VALUES (
    '008a0bd6-81ea-4d02-8c07-4d6342b5a5bd',
    (SELECT id FROM topics WHERE name = 'Conflictos laborales y autonomía profesional' AND subject_id = (SELECT id FROM subjects WHERE name = 'Ciencias Sociales') LIMIT 1),
    (SELECT id FROM subjects WHERE name = 'Ciencias Sociales'),
    'Los pilotos de una compañía aérea están inconformes con su situación laboral. Argumentan que la responsabilidad que implica su trabajo no se tiene en cuenta a la hora de definir los aumentos salariales, que durante los últimos años se han hecho de acuerdo con la inflación. Como respuesta, la compañía propone un esquema de compensación salarial de acuerdo con el desempeño individual de cada piloto, determinado por la cantidad de combustible que le ahorra a la empresa y la reducción de tiempo de cada vuelo. Los pilotos no aceptan la propuesta porque dicen que se podrían llegar a tomar decisiones que ponen en riesgo la seguridad del vuelo por no consumir más combustible y llegar más rápidamente. En esta situación, los pilotos tendrían dificultad en llegar a un acuerdo sobre su remuneración, porque ellos consideran que',
    'multiple_choice',
    5,
    'D',
    '{"A": "su desempe\u00f1o individual es insuficiente para lograr una remuneraci\u00f3n adicional fundamentada en este.", "B": "la compa\u00f1\u00eda a\u00e9rea no tiene en cuenta en su propuesta, el precio de los combustibles ni las largas horas de trabajo que debe asumir cada piloto en jornadas de vuelos internacionales.", "C": "tienen dificultades en manejar las cambiantes condiciones meteorol\u00f3gicas y las exigencias t\u00e9cnicas de las aeronaves.", "D": "la compa\u00f1\u00eda a\u00e9rea no tiene en cuenta la responsabilidad que tienen pilotos y la importancia de que puedan tomar decisiones sin condicionamientos."}',
    'Incentivos económicos pueden comprometer criterio profesional',
    'Identifica tensión autonomía-incentivos',
    '["Pensamiento reflexivo y sist\u00e9mico", "Analizar"]',
    '{"discrimination_index": 0.5, "success_rate": 0.6, "estimated_time": 3, "xp_reward": 20, "original_id": "246", "bank_origin": "ICFES_OFICIAL"}',
    'Los pilotos de una compañía aérea están inconformes con su situación laboral. Argumentan que la responsabilidad que implica su trabajo no se tiene en cuenta a la hora de definir los aumentos salariales, que durante los últimos años se han hecho de acuerdo con la inflación. Como respuesta, la compañía propone un esquema de compensación salarial de acuerdo con el desempeño individual de cada piloto, determinado por la cantidad de combustible que le ahorra a la empresa y la reducción de tiempo de cada vuelo. Los pilotos no aceptan la propuesta porque dicen que se podrían llegar a tomar decisiones que ponen en riesgo la seguridad del vuelo por no consumir más combustible y llegar más rápidamente. En esta situación, los pilotos tendrían dificultad en llegar a un acuerdo sobre su remuneración, porque ellos consideran que',
    NULL,
    'su desempeño individual es insuficiente para lograr una remuneración adicional fundamentada en este.',
    'la compañía aérea no tiene en cuenta en su propuesta, el precio de los combustibles ni las largas horas de trabajo que debe asumir cada piloto en jornadas de vuelos internacionales.',
    'tienen dificultades en manejar las cambiantes condiciones meteorológicas y las exigencias técnicas de las aeronaves.',
    'la compañía aérea no tiene en cuenta la responsabilidad que tienen pilotos y la importancia de que puedan tomar decisiones sin condicionamientos.',
    'd'
);

-- Question 227: Ciencias Sociales
INSERT INTO topics (id, subject_id, name, description, difficulty_level)
VALUES ('9c302d2c-7b26-4181-8cab-3d85cbc3e98c', (SELECT id FROM subjects WHERE name = 'Ciencias Sociales'), 'Biopiratería y conocimientos tradicionales', 'Tema: Biopiratería y conocimientos tradicionales', 1)
