VALUES ('8b6f9ea5-cca2-494b-bfd6-d50d854b0300', (SELECT id FROM subjects WHERE name = 'Ciencias Sociales'), 'Prioridades de desarrollo y competitividad', 'Tema: Prioridades de desarrollo y competitividad', 1)
