VALUES ('3ff1b548-a766-4dbd-a386-746d3a6d29df', (SELECT id FROM subjects WHERE name = 'Ciencias Sociales'), 'Procesos democráticos y negociación', 'Tema: Procesos democráticos y negociación', 1)
