VALUES ('f2836bc3-05a7-4c4f-8e75-23f486e9e4e8', (SELECT id FROM subjects WHERE name = 'Ciencias Sociales'), 'Políticas urbanas integrales', 'Tema: Políticas urbanas integrales', 1)
