INSERT INTO questions (
    id, topic_id, subject_id, question_text, question_type,
    difficulty, correct_answer, options, explanation, hint,
    tags, power_stats,
    pregunta_texto, pregunta_imagen,
    opcion_a_texto, opcion_b_texto, opcion_c_texto, opcion_d_texto,
    respuesta_correcta
) VALUES (
    '05cd328f-d098-4c9e-8273-cffc6726ffa2',
    (SELECT id FROM topics WHERE name = 'Políticas urbanas integrales' AND subject_id = (SELECT id FROM subjects WHERE name = 'Ciencias Sociales') LIMIT 1),
    (SELECT id FROM subjects WHERE name = 'Ciencias Sociales'),
    'Un estudio realizado por la Organización de las Naciones Unidas (ONU) sostiene que América Latina es la región más urbanizada del mundo. Aunque esto aumenta las oportunidades laborales y mejora las condiciones de vida de muchas personas, su costo económico, social y ambiental es demasiado alto, ya que han proliferado –y seguirán aumentando– barrios pobres y desiguales que expanden el casco urbano e invaden zonas rurales. Para atender este problema, el estudio plantea tres propuestas. La primera es densificar las ciudades; así, en lugar de expandirse hacia zonas rurales, donde se producen los alimentos, se aumenta la vivienda vertical (edificios). La segunda solución es acelerar las reformas urbanas para legalizar los barrios de invasión, ofreciéndoles a quienes habitan allí acceso a servicios públicos y títulos de propiedad. La tercera alternativa es aumentar la oferta de transporte público, lo cual ayudaría a facilitar la movilidad desde la periferia hacia los centros urbanos. ¿Qué tipo de relación se puede establecer entre las propuestas de solución al problema de la urbanización en América Latina?',
    'multiple_choice',
    5,
    'C',
    '{"A": "Complementariedad, pues todas las soluciones priorizan el desarrollo econ\u00f3mico de los centros urbanos.", "B": "Compatibilidad, pues todas las soluciones se enfocan hacia la recuperaci\u00f3n de las zonas de producci\u00f3n rural.", "C": "Complementariedad, pues todas las soluciones se enfocan hacia la mitigaci\u00f3n de los costos sociales y econ\u00f3micos de la expansi\u00f3n urbana.", "D": "Compatibilidad, pues todas las soluciones priorizan el mejoramiento de la calidad de vida de los habitantes provenientes de zonas rurales."}',
    'Las tres propuestas abordan diferentes aspectos del mismo problema',
    'Analiza complementariedad de políticas',
    '["Pensamiento reflexivo y sist\u00e9mico", "Comprender"]',
    '{"discrimination_index": 0.5, "success_rate": 0.6, "estimated_time": 3, "xp_reward": 20, "original_id": "264", "bank_origin": "ICFES_OFICIAL"}',
    'Un estudio realizado por la Organización de las Naciones Unidas (ONU) sostiene que América Latina es la región más urbanizada del mundo. Aunque esto aumenta las oportunidades laborales y mejora las condiciones de vida de muchas personas, su costo económico, social y ambiental es demasiado alto, ya que han proliferado –y seguirán aumentando– barrios pobres y desiguales que expanden el casco urbano e invaden zonas rurales. Para atender este problema, el estudio plantea tres propuestas. La primera es densificar las ciudades; así, en lugar de expandirse hacia zonas rurales, donde se producen los alimentos, se aumenta la vivienda vertical (edificios). La segunda solución es acelerar las reformas urbanas para legalizar los barrios de invasión, ofreciéndoles a quienes habitan allí acceso a servicios públicos y títulos de propiedad. La tercera alternativa es aumentar la oferta de transporte público, lo cual ayudaría a facilitar la movilidad desde la periferia hacia los centros urbanos. ¿Qué tipo de relación se puede establecer entre las propuestas de solución al problema de la urbanización en América Latina?',
    NULL,
    'Complementariedad, pues todas las soluciones priorizan el desarrollo económico de los centros urbanos.',
    'Compatibilidad, pues todas las soluciones se enfocan hacia la recuperación de las zonas de producción rural.',
    'Complementariedad, pues todas las soluciones se enfocan hacia la mitigación de los costos sociales y económicos de la expansión urbana.',
    'Compatibilidad, pues todas las soluciones priorizan el mejoramiento de la calidad de vida de los habitantes provenientes de zonas rurales.',
    'c'
);

