    'multiple_choice',
    5,
    'B',
    '{"A": "Revoluci\u00f3n nicarag\u00fcense, Revoluci\u00f3n rusa, Revoluci\u00f3n mexicana, Revoluci\u00f3n cubana.", "B": "Revoluci\u00f3n mexicana, Revoluci\u00f3n rusa, Revoluci\u00f3n cubana, Revoluci\u00f3n nicarag\u00fcense.", "C": "Revoluci\u00f3n rusa, Revoluci\u00f3n cubana, Revoluci\u00f3n mexicana, Revoluci\u00f3n nicarag\u00fcense.", "D": "Revoluci\u00f3n cubana, Revoluci\u00f3n rusa, Revoluci\u00f3n mexicana, Revoluci\u00f3n nicarag\u00fcense."}',
