    '0ceeb0be-e070-4088-ab8a-f94ef7c14d5c',
    (SELECT id FROM topics WHERE name = 'División porcentual' AND subject_id = (SELECT id FROM subjects WHERE name = 'Matemáticas') LIMIT 1),
