    '{"discrimination_index": 0.5, "success_rate": 0.6, "estimated_time": 85, "xp_reward": 10, "original_id": "MAT_2025_026", "bank_origin": "ICFES_OFICIAL"}',
    '¿Cuánto porcentaje tendrá cada pregunta del examen de juan?',
    NULL,
    '0.00475',
    '0.05',
    '0.0625',
    '0.00625',
    'd'
);

